create table public.work_order_inputs(id uuid primary key default gen_random_uuid(),work_order_id uuid not null references public.field_operations(id)on delete cascade,item_id uuid not null references public.inventory_items(id)on delete restrict,dose_per_hectare numeric(16,3)not null check(dose_per_hectare>0),required_quantity numeric(16,3)not null check(required_quantity>0),reserved_quantity numeric(16,3)not null default 0,actual_quantity numeric(16,3),unit_value_ars numeric(16,2)not null default 0,created_by uuid not null references public.profiles(id),unique(work_order_id,item_id));
create table public.purchase_requests(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,work_order_id uuid references public.field_operations(id)on delete set null,item_id uuid references public.inventory_items(id)on delete set null,requested_on date not null default current_date,needed_by date not null,item_name text not null,quantity numeric(16,3)not null check(quantity>0),unit text not null,estimated_unit_price_ars numeric(16,2)not null default 0,suggested_supplier text,status text not null default 'pendiente'check(status in('pendiente','autorizada','ordenada','recibida_parcial','recibida','anulada')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
alter table public.work_order_inputs enable row level security;alter table public.purchase_requests enable row level security;create policy order_inputs_access on public.work_order_inputs for all to authenticated using(exists(select 1 from public.field_operations o where o.id=work_order_id and public.can_access_farm(o.farm_id)))with check(exists(select 1 from public.field_operations o where o.id=work_order_id and public.can_manage_farm(o.farm_id)));create policy requests_access on public.purchase_requests for all to authenticated using(public.can_access_farm(farm_id))with check(public.can_manage_farm(farm_id));
create or replace function public.assign_work_order_input(p_work_order_id uuid,p_item_id uuid,p_dose numeric)returns uuid language plpgsql security definer set search_path=''as $$declare v_order public.field_operations;v_item public.inventory_items;v_available numeric;v_required numeric;v_reserved numeric;v_input uuid;begin select * into v_order from public.field_operations where id=p_work_order_id for update;select * into v_item from public.inventory_items where id=p_item_id for update;if v_order.id is null or v_item.id is null or v_order.farm_id<>v_item.farm_id or not public.can_manage_farm(v_order.farm_id)then raise exception 'Orden o insumo inválido'using errcode='42501';end if;v_required:=round(v_order.worked_hectares*p_dose,3);select greatest(available_quantity,0)into v_available from public.inventory_position where id=p_item_id;v_reserved:=least(v_required,v_available);insert into public.work_order_inputs(work_order_id,item_id,dose_per_hectare,required_quantity,reserved_quantity,unit_value_ars,created_by)values(v_order.id,v_item.id,p_dose,v_required,v_reserved,v_item.unit_value_ars,auth.uid())on conflict(work_order_id,item_id)do update set dose_per_hectare=excluded.dose_per_hectare,required_quantity=excluded.required_quantity,reserved_quantity=excluded.reserved_quantity,unit_value_ars=excluded.unit_value_ars returning id into v_input;if v_reserved>0 then insert into public.inventory_movements(item_id,movement_date,movement_type,quantity,concept,reference,work_order_id,created_by)values(v_item.id,current_date,'reserva',v_reserved,'Reserva para '||v_order.name,'Orden de trabajo',v_order.id,auth.uid());end if;if v_required>v_reserved then insert into public.purchase_requests(farm_id,work_order_id,item_id,needed_by,item_name,quantity,unit,estimated_unit_price_ars,status,created_by)values(v_order.farm_id,v_order.id,v_item.id,v_order.operation_date,v_item.name,v_required-v_reserved,v_item.unit,v_item.unit_value_ars,'pendiente',auth.uid());end if;return v_input;end;$$;
create or replace function public.execute_work_order(p_work_order_id uuid)returns void language plpgsql security definer set search_path=''as $$declare v_order public.field_operations;v_line public.work_order_inputs;v_stock numeric;v_actual numeric;begin select * into v_order from public.field_operations where id=p_work_order_id for update;if v_order.id is null or not public.can_manage_farm(v_order.farm_id)then raise exception 'Orden inválida'using errcode='42501';end if;for v_line in select * from public.work_order_inputs where work_order_id=v_order.id loop v_actual:=coalesce(v_line.actual_quantity,v_line.required_quantity);select theoretical_quantity into v_stock from public.inventory_position where id=v_line.item_id;if v_actual>v_stock then raise exception 'Stock insuficiente para ejecutar la orden';end if;if v_line.reserved_quantity>0 then insert into public.inventory_movements(item_id,movement_date,movement_type,quantity,concept,reference,work_order_id,created_by)values(v_line.item_id,current_date,'liberacion',v_line.reserved_quantity,'Liberación al ejecutar orden',v_order.name,v_order.id,auth.uid());end if;insert into public.inventory_movements(item_id,movement_date,movement_type,quantity,concept,reference,work_order_id,created_by)values(v_line.item_id,current_date,'egreso',v_actual,'Consumo real en '||v_order.name,'Orden ejecutada',v_order.id,auth.uid());update public.work_order_inputs set actual_quantity=v_actual,reserved_quantity=0 where id=v_line.id;end loop;update public.field_operations set status='realizada',updated_at=now()where id=v_order.id;end;$$;grant execute on function public.assign_work_order_input(uuid,uuid,numeric)to authenticated;grant execute on function public.execute_work_order(uuid)to authenticated;
create view public.work_order_supply_status with(security_invoker=true)as select w.id,w.farm_id,f.name farm_name,w.name order_name,w.operation_date,w.status,w.worked_hectares,i.id input_id,s.name item_name,s.unit,i.dose_per_hectare,i.required_quantity,i.reserved_quantity,greatest(i.required_quantity-i.reserved_quantity,0)missing_quantity,i.unit_value_ars,i.required_quantity*i.unit_value_ars planned_input_cost from public.field_operations w join public.farms f on f.id=w.farm_id left join public.work_order_inputs i on i.work_order_id=w.id left join public.inventory_items s on s.id=i.item_id;grant select on public.work_order_supply_status to authenticated;
